// Join SleeperPlayerId from Players collection via GsisId
// Players in Postgres are not here — we use the existing sim docs as a lookup
// Build GsisId -> SleeperPlayerId map from existing 2024 sim docs
var gsisMap = {};
db.simulation_results.find({ Season: 2024 }, { PlayerId: 1, SleeperPlayerId: 1 }).forEach(function(d) {
  if (d.SleeperPlayerId) gsisMap[d.PlayerId] = d.SleeperPlayerId;
});
print('GsisId->SleeperPlayerId map size: ' + Object.keys(gsisMap).length);

var inserted = 0; var skipped = 0;
docs.forEach(function(doc) {
  var sleeperId = gsisMap[doc.GsisId];
  delete doc.GsisId;
  if (sleeperId) {
    doc.SleeperPlayerId = sleeperId;
  } else {
    skipped++;
  }
  db.simulation_results.insertOne(doc);
  inserted++;
});
print('Inserted: ' + inserted + '  Skipped (no SleeperPlayerId): ' + skipped);
print('Total 2025 docs: ' + db.simulation_results.countDocuments({ Season: 2025 }));